import{z as s,x as o,o as e,c as i,q as t,j as l,D as E,d as r,s as B,S as n}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"投机实验方法","description":"","frontmatter":{"title":"投机实验方法","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/spec-experiment-method.md","filePath":"llm/spec-experiment-method.md","lastUpdated":1791063341000}'),m={name:"llm/spec-experiment-method.md"};function p(c,a,h,d,C,D){const A=o("Mermaid");return e(),i("div",null,[a[2]||(a[2]=t('<h1 id="投机实验方法" tabindex="-1">投机实验方法 <a class="header-anchor" href="#投机实验方法" aria-label="Permalink to &quot;投机实验方法&quot;">​</a></h1><div class="epigraph"><p>投机解码是加速比注水最方便的领域：温度、批量、草稿成本各藏一个数量级，每个数字都要先问口径。</p><footer>—— 据 Leviathan et al., 2023 与 Cai et al., 2024 等论文的实验设定对照整理</footer></div><p><a href="/llm/spec-quant-combo">上一课</a>的结尾立了一条口径纪律。本课把纪律展开成方法：怎么设计、跑、报一个投机实验。前面十一课里反复出现「钉住批量」「分桶报 \\(\\alpha\\)」「别跨表乘算」，本课把它们收拢成一套可执行的动作清单。已有的邻居各管一段：<a href="/llm/spec-acceptance-theory">接受率的理论与测量</a>给定义与估计量，<a href="/llm/kv-measurement-pitfalls">KV 测量陷阱</a>给服务指标的坑，<a href="/llm/serving-metrics">服务指标</a>给口径；本课只写投机特有的部分。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>投机实验的每个环节都自带放大器。<strong>设定放大器</strong>：batch=1、温度 0、贪心、短输出，四个开关各拨一下，加速比可以翻倍——而部署环境常常四个全反过来。<a href="/llm/spec-acceptance-rate">接受率与加速比</a>提醒过 1.8–4 倍钉在各自设定上，实践中真正的问题是没人把设定写全。<strong>归因放大器</strong>：加速比是比值，分母里藏着草稿成本、校验增宽、KV 峰值；只报分子，任何实现退化都能藏进分母。<strong>外推放大器</strong>：单请求微批测出的数，经过连续批调度、变长形状、量化联评（上一课的减法）之后所剩无几；拿微批数做上线决策，常常买回一台更慢的服务。</p><p><span class="marginnote">数字实例：同一实现，batch=1、温度 0、贪心下报 3.5 倍；换到批量 32、温度 1 的服务负载可能只剩 1.2 倍。四个开关每一个都可能砍掉一大截，「峰值」与「均值」之间隔的不是噪声，是四层口径差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按四级口径报数，每级标明条件。<strong>第一级：分布重叠</strong>。逐位置 \\(\\hat\\alpha\\) 按温度、任务、输出位置分桶，估计量用上一课的协议；贪心一致率单独一栏。<strong>第二级：单请求墙钟</strong>。钉死温度与采样器，报 \\(\\tau\\) 的分布（不只均值）、每轮耗时分解（草稿 / 校验 / 开销），设备与精度档写明。<strong>第三级：服务负载</strong>。连续批下扫批量，报吞吐–延迟曲线与 p50/p99 TPOT、完成时间分位数；混合批与变长树的真实形状进测量，不用补齐到最大的假形状。<a href="/llm/kv-measurement-pitfalls">KV 测量陷阱</a>的双口径纪律原样适用：投机开与关各测一遍稳态。<strong>第四级：端到端验收</strong>。真实流量影子或灰度，桶账（<a href="/llm/spec-online-draft-selection">在线草稿模型选择</a>）与质量指标并列——有偏变体（typical acceptance 一类）必须过质量关，无损变体也建议抽检，防止实现层的静默偏差。<strong>消融顺序</strong>固定：先 \\(\\gamma\\) 扫描，再树预算，最后换草稿家族；一次只动一个。<strong>统计</strong>：同设定多跑取方差，单次数字不进决策。</p>',8)),(e(),l(n,null,{default:E(()=>[B(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E7%AC%AC%E4%B8%80%E7%BA%A7%EF%BC%9A%E5%88%86%E6%A1%B6%20%CE%B1%22%5D%20--%3E%20L2%5B%22%E7%AC%AC%E4%BA%8C%E7%BA%A7%EF%BC%9A%E5%8D%95%E8%AF%B7%E6%B1%82%20%CF%84%20%E5%88%86%E5%B8%83%E4%B8%8E%E8%80%97%E6%97%B6%E5%88%86%E8%A7%A3%22%5D%0A%20%20L2%20--%3E%20L3%5B%22%E7%AC%AC%E4%B8%89%E7%BA%A7%EF%BC%9A%E6%89%AB%E6%89%B9%E9%87%8F%E7%9A%84%E5%90%9E%E5%90%90%E2%80%93%E5%BB%B6%E8%BF%9F%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20L3%20--%3E%20L4%5B%22%E7%AC%AC%E5%9B%9B%E7%BA%A7%EF%BC%9A%E5%BD%B1%E5%AD%90%E6%B5%81%E9%87%8F%20%2B%20%E8%B4%A8%E9%87%8F%E9%AA%8C%E6%94%B6%22%5D%0A%20%20L1%20--%3E%20COND%7B%22%E6%AF%8F%E7%BA%A7%E6%A0%87%E6%98%8E%EF%BC%9A%E6%B8%A9%E5%BA%A6%20%2F%20%E6%89%B9%E9%87%8F%20%2F%20%E7%B2%BE%E5%BA%A6%E6%A1%A3%22%7D%0A%20%20COND%20--%3E%20L2%0A%20%20L2%20--%3E%20L3%0A%20%20L3%20--%3E%20DEC%5B%22%E4%B8%8A%E7%BA%BF%E5%86%B3%E7%AD%96%EF%BC%9A%E6%A1%B6%E8%B4%A6%20%2B%20p99%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>四级口径的机制是混杂因素的逐级叠加：第一级只有分布重叠，干净；第二级加进草稿与校验的真实耗时；第三级加进批调度与形状混杂；第四级加进流量漂移与质量约束。每一级都是上一级加新混杂，所以「报哪一级」取决于「主张哪一级」：主张草稿好坏看一级，主张端上收益看二级，主张服务收益看三级，主张该不该开投机看四级。跨级引用数字是这类实验最常见的结构病——草稿论文报一级，服务团队要的是三级，中间隔着的正是<a href="/llm/spec-batching-interaction">投机与批处理的交互</a>那道 roofline。消融顺序的机制则在于耦合：\\(\\gamma\\) 与树宽决定校验形状，形状改变 \\(c_{\\mathrm{tgt}}\\)，\\(c_{\\mathrm{tgt}}\\) 反过来改写草稿之间的排序——先定形状再比草稿，否则排序随形状漂。</p><p><span class="marginnote">一个自检问题足够拦下大半注水：「这个 3 倍的分母里，草稿的 KV、预热和校验增宽各算了多少？」答不出分母构成的加速比，默认不采信。</span></p><p><span class="marginnote">常见误区：只盯分子「每轮多吐几个 token」。分母里草稿前向、KV 峰值、校验增宽任何一项悄悄变差，分子再好看整体也可能更慢——加速比注水最方便的位置从来是分母，因为没人盯着它。</span></p>',4)),(e(),l(n,null,{default:E(()=>[B(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%85%88%E5%8A%A8%20%CE%B3%22%5D%20--%3E%20SH%5B%22%E6%A0%A1%E9%AA%8C%E5%BD%A2%E7%8A%B6%E6%94%B9%E5%8F%98%22%5D%0A%20%20T%5B%22%E5%86%8D%E5%8A%A8%E6%A0%91%E5%AE%BD%22%5D%20--%3E%20SH%0A%20%20SH%20--%3E%20C%5B%22%E6%88%90%E6%9C%AC%E6%AF%94%20c_tgt%20%E6%94%B9%E5%86%99%22%5D%0A%20%20C%20--%3E%20R%5B%22%E8%8D%89%E7%A8%BF%E5%AE%B6%E6%97%8F%E4%B9%8B%E9%97%B4%E9%87%8D%E6%96%B0%E6%8E%92%E5%BA%8F%22%5D%0A%20%20R%20--%3E%20D%7B%22%E5%BD%A2%E7%8A%B6%E9%92%89%E6%AD%BB%E5%90%8E%E5%86%8D%E6%AF%94%E8%8D%89%E7%A8%BF%3F%22%7D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20OK%5B%22%E6%8E%92%E5%BA%8F%E5%8F%AF%E6%AF%94%2C%20%E6%B6%88%E8%9E%8D%E6%9C%89%E6%95%88%22%5D%0A%20%20D%20--%3E%7C%22%E5%90%A6%3A%20%E5%85%88%E6%8D%A2%E8%8D%89%E7%A8%BF%E5%90%8E%E5%AE%9A%E5%BD%A2%E7%8A%B6%22%7C%20BAD%5B%22%E6%8E%92%E5%BA%8F%E9%9A%8F%E5%BD%A2%E7%8A%B6%E6%BC%82%E7%A7%BB%2C%20%E7%BB%93%E8%AE%BA%E4%BD%9C%E5%BA%9F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>实验室里测不到的：热节流与邻租噪声让端侧与共享集群的单次运行方差很大，多跑不是可选项。影子流量有反身性：投机改变请求的驻留时间，流量本身被实验改写，灰度结论要留意时段与配额。跨框架比较（不同推理引擎自带的投机实现）把内核与调度的差异混进方法差异，结论只能落在「这套栈」上。最后，本课给的是投机特有的方法；通用的服务压测与指标定义以<a href="/llm/serving-metrics">服务指标</a>与<a href="/llm/kv-measurement-pitfalls">KV 测量陷阱</a>为准，两处已写的纪律不在此重复。</p><p><span class="marginnote">直觉类比：消融顺序像调菜谱——先定火候（\\(\\gamma\\) 与树宽决定「锅」的形状），再换食材（草稿家族）。同一种食材在不同火候下排名不同，火候没定时比食材，比出来的只是噪音。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四级口径逐级加混杂：分桶 \\(\\alpha\\) → 单请求 \\(\\tau\\) 与耗时分解 → 扫批量的吞吐–延迟曲线 → 影子流量加质量验收。</li><li>主张到哪一级、数字报到哪一级；跨级引用是投机实验最常见的结构病。</li><li>加速比是比值：分母里草稿成本、校验增宽、KV 峰值必须交代，答不出分母的数字不采信。</li><li>消融顺序先 \\(\\gamma\\)、再树、后草稿：形状决定成本比，成本比改写草稿排序。</li><li>有偏变体必须过质量关；无损变体也建议抽检实现层偏差。</li><li>出处：Leviathan et al., ICML 2023；Cai et al., ICML 2024；Li et al., EAGLE 系列；据本仓库测量课序综合。</li></ul>',5))])}const f=s(m,[["render",p]]);export{g as __pageData,f as default};
